1	//! Saga 21.5 step 008: browser-only `RemoteEvaluator` impls.
2	//!
3	//! Lifted out of `eval.rs` so the parent module stays under its
4	//! 500-line file budget. Every fn is `#[cfg(target_arch =
5	//! "wasm32")]` because the entire module body would otherwise
6	//! force `gloo::net` + `wasm_bindgen_futures` on native builds.
7	//! `cargo test` compiles this file but elides every function;
8	//! the WASM build (`scripts/build-pages.sh`) wires them in.
9	//!
10	//! Saga 77: HTTP helper bodies (`wasm_create_session`,
11	//! `wasm_eval_stream`, `wasm_eval_stream_inner`) moved to
12	//! `eval_wasm_helpers.rs` so the parent stays under the
13	//! module-function-count limit.
14	
15	#![cfg(target_arch = "wasm32")]
16	
17	use crate::eval::current_connect_url_from_window;
18	use crate::eval::{Evaluator, MetricCb, RemoteEvaluator, ResultCb, StreamCb};
19	use crate::eval_wasm_helpers::{wasm_create_session, wasm_eval_stream, with_deadline};
20	
21	thread_local! {
22	    // One persistent RemoteEvaluator per page so the server-side
23	    // session (workspace state) is reused across submitted lines.
24	    static CONNECT_EVALUATOR: std::cell::RefCell<Option<RemoteEvaluator>> =
25	        const { std::cell::RefCell::new(None) };
26	}
27	
28	/// Connect-mode one-shot eval. When `?connect=<url>` is present in
29	/// the page URL, route `program` to that `mlpl-serve` over the
30	/// REST eval API (async, server-side) and fire `on_result` with
31	/// the server's value -- so `llm_call` / MLX-GPU work run on the
32	/// server and never block (or panic) the browser. Returns true
33	/// when it took the eval; false (leaving `on_result` uncalled)
34	/// when no connect URL is set, so the caller does local eval.
35	pub fn connect_eval(program: &str, on_result: ResultCb) -> bool {
36	    let Some(url) = current_connect_url_from_window() else {
37	        return false;
38	    };
39	    // The browser will block this fetch (https page -> http server) before it
40	    // leaves the tab. Short-circuit with a clear explanation instead of a
41	    // cryptic "Failed to fetch".
42	    if let Some(reason) = crate::connect_guard::connect_blocked_reason() {
43	        on_result(format!("error: {reason}"));
44	        return true;
45	    }
46	    CONNECT_EVALUATOR.with(|cell| {
47	        if cell.borrow().is_none() {
48	            *cell.borrow_mut() = Some(RemoteEvaluator::new(url));
49	        }
50	        cell.borrow()
51	            .as_ref()
52	            .expect("evaluator set above")
53	            .eval(program, on_result);
54	    });
55	    true
56	}
57	
58	impl Evaluator for RemoteEvaluator {
59	    fn eval(&self, program: &str, on_result: ResultCb) {
60	        let base = self.base_url().to_string();
61	        let state = self.state_handle();
62	        let program = program.to_string();
63	        wasm_bindgen_futures::spawn_local(async move {
64	            let result = wasm_eval(&base, &state, &program).await;
65	            on_result(result);
66	        });
67	    }
68	    fn clear(&self) {
69	        self.clear_state();
70	    }
71	}
72	
73	async fn wasm_eval(
74	    base_url: &str,
75	    state: &std::cell::RefCell<Option<crate::eval::RemoteSession>>,
76	    program: &str,
77	) -> String {
78	    if state.borrow().is_none() {
79	        match wasm_create_session(base_url).await {
80	            Ok(s) => *state.borrow_mut() = Some(s),
81	            Err(e) => return format!("error: {e}"),
82	        }
83	    }
84	    let s = state
85	        .borrow()
86	        .as_ref()
87	        .expect("session created above")
88	        .clone();
89	    let url = format!(
90	        "{}/v1/sessions/{}/eval",
91	        base_url.trim_end_matches('/'),
92	        s.session_id
93	    );
94	    let req = match gloo::net::http::Request::post(&url)
95	        .header("Authorization", &format!("Bearer {}", s.token))
96	        .header("Content-Type", "application/json")
97	        .body(serde_json::json!({"program": program}).to_string())
98	    {
99	        Ok(r) => r,
100	        Err(e) => return format!("error: {e}"),
101	    };
102	    // Generous deadline: a connect eval can legitimately run minutes --
103	    // a CPU base-pretrain step (e.g. the CUDA LoRA demo's `train 40` over
