300	    /// paths and absolute URLs. The WASM equivalent
301	    /// (`fetch_viz_async`) lives in `eval_wasm.rs`.
302	    pub fn fetch_viz(&self, viz_url: &str, bearer: &str) -> Result<(Vec<u8>, String), String> {
303	        let url = resolve_viz_url(&self.base_url, viz_url);
304	        let resp = reqwest::blocking::Client::new()
305	            .get(&url)
306	            .bearer_auth(bearer)
307	            .send()
308	            .map_err(|e| e.to_string())?;
309	        if !resp.status().is_success() {
310	            return Err(format!("fetch_viz: {}", resp.status()));
311	        }
312	        let content_type = resp
313	            .headers()
314	            .get("content-type")
315	            .and_then(|v| v.to_str().ok())
316	            .unwrap_or("application/octet-stream")
