323	#[cfg(not(target_arch = "wasm32"))]
324	fn native_eval_stream(
325	    base_url: &str,
326	    state: &RefCell<Option<RemoteSession>>,
327	    program: &str,
328	    mut on_metric: MetricCb,
329	) -> StreamOutcome {
330	    if state.borrow().is_none() {
331	        match native_create_session(base_url) {
332	            Ok(s) => *state.borrow_mut() = Some(s),
333	            Err(e) => return StreamOutcome::Error { message: e },
334	        }
335	    }
336	    let s = state.borrow().as_ref().expect("session created").clone();
337	    let url = format!(
338	        "{}/v1/sessions/{}/eval_stream",
339	        base_url.trim_end_matches('/'),
340	        s.session_id
341	    );
342	    let resp = match reqwest::blocking::Client::new()
343	        .post(&url)
344	        .bearer_auth(&s.token)
345	        .json(&serde_json::json!({"program": program}))
346	        .send()
347	    {
348	        Ok(r) => r,
349	        Err(e) => {
350	            return StreamOutcome::Error {
351	                message: e.to_string(),
352	            };
353	        }
354	    };
355	    if !resp.status().is_success() {
356	        let body = resp.text().unwrap_or_default();
357	        let message = serde_json::from_str::<serde_json::Value>(&body)
358	            .ok()
359	            .and_then(|v| v.get("error").and_then(|e| e.as_str()).map(str::to_string))
360	            .unwrap_or(body);
361	        return StreamOutcome::Error { message };
362	    }
363	    let reader = std::io::BufReader::new(resp);
364	    crate::eval_sse::parse_sse_stream(reader, &mut on_metric)
365	}
366	
367	#[cfg(not(target_arch = "wasm32"))]
368	fn native_create_session(base_url: &str) -> Result<RemoteSession, String> {
369	    let url = format!("{}/v1/sessions", base_url.trim_end_matches('/'));
370	    let body: serde_json::Value = reqwest::blocking::Client::new()
371	        .post(&url)
372	        .send()
373	        .map_err(|e| e.to_string())?
374	        .json()
375	        .map_err(|e| e.to_string())?;
376	    let session_id = body
377	        .get("session_id")
378	        .and_then(|v| v.as_str())
379	        .ok_or("missing session_id")?
380	        .to_string();
381	    let token = body
382	        .get("token")
383	        .and_then(|v| v.as_str())
384	        .ok_or("missing token")?
385	        .to_string();
386	    Ok(RemoteSession { session_id, token })
387	}
