1	//! Connect-mode eval dispatch. When the page is opened with
2	//! `?connect=<url>`, real expressions (and the `:ask` Ollama
3	//! shortcut) are sent to `mlpl-serve` and evaluated server-side,
4	//! so `llm_call` / MLX-GPU work run there and the browser never
5	//! blocks (or panics on WASM-unsupported HTTP/time). Whole module
6	//! is WASM-only; native builds compile it away.
7	
8	#![cfg(target_arch = "wasm32")]
9	
10	use mlpl_web_eval::state::{EntryKind, HistoryEntry};
11	use mlpl_web_handlers_upload::eval_deps::EvalDeps;
12	
13	/// Default Ollama endpoint + model backing the `:ask` shortcut.
14	/// Overridable per page via `?ollama=<url>` / `?model=<name>` so
15	/// the demo can point at a remote GPU box + a bigger tool-capable
16	/// model (e.g. `?ollama=http://large12:11434&model=qwen2.5-coder:14b`).
17	/// mlpl-serve runs the `llm_call` server-side, so the target host
18	/// just has to be reachable from the server (no browser CORS).
19	const ASK_URL: &str = "http://localhost:11434";
20	const ASK_MODEL: &str = "qwen2.5:0.5b";
21	
22	/// System/meta preamble prepended to every `:ask` so even broad
23	/// questions ("describe this environment") are grounded in what
24	/// MLPL is and what context the user can surface, rather than the
25	/// model guessing about generic OS/web environments.
26	const ASK_SYSTEM: &str = "You are an assistant embedded INSIDE the sw-MLPL REPL -- an APL/J/BQN-inspired array and tensor language for machine learning, with a 3D visualization playground (the REPL renders each result as a 3D sculpture: tensors as grids/bars, attention as heatmaps, models as Sankey diagrams). You are NOT a generic cloud/AWS/web assistant; EVERY question is about sw-MLPL. \
27	CRITICAL: Do NOT invent, guess, or hallucinate commands, syntax, model names, or features. If you are unsure, say so plainly and tell the user to run `:help`. The ONLY REPL commands are exactly these -- never claim any other exists: :help, :help <topic>, :<cmd> --help, :vars, :models, :tokenizers, :fns, :builtins, :describe <name>, :history, :experiments, :wsid, :status, :status watch, :reset, :ask <prompt>, :connect list, :connect set <model>, :3d, :2d, :clear, :upload <name>. There is NO :load_model, NO :model, NO :search. \
28	DO NOT WRITE MLPL CODE unless you are CERTAIN of the exact syntax (ideally only code you can see in this session's context): MLPL is an array language, NOT Python -- it has NO `+=`/`-=`, NO `==` (use `eq(a, b)`), NO lambdas or `->`, NO `filter`/`map`/`print`/`length`/`strcat`/`append`, and `device(\"...\")`, `experiment`, and `train`/`repeat` ALWAYS take a `{ ... }` block (a bare `device(\"mlx\")` is a syntax error). If you are not sure code will run, DESCRIBE the approach in plain words and tell the user to read the demo/its literate walkthrough and `:help` -- never emit a code block you have not actually seen run. When the user asks how to do something in the REPL: for command help tell them to run `:help` (lists all commands) or `:<cmd> --help` (help for one command, e.g. `:ask --help`); to see or change which LLM answers their `:ask`, tell them `:connect list` (lists the installed Ollama models) then `:connect set <name>`. \
29	The user's recent REPL activity and any selected 3D sculpture are provided below as your context -- use them. Answer concisely and specifically about sw-MLPL.";
30	
31	/// Compact MLPL syntax cheat-sheet prepended to the builtin signatures in
32	/// [`mlpl_reference`]. The CORRECT forms (vs the Python-isms the prompt
33	/// forbids), so when code is warranted the model writes valid MLPL.
34	const MLPL_SYNTAX: &str = " MLPL quick reference -- use EXACTLY these forms. \
35	Assign `name = expr`; comment `# ...`; compare with `eq(a,b)` / `gt(a,b)` / `lt(a,b)` (there is no `==`/`<`/`>`); \
36	EVERY block uses braces: `device(\"mlx\") { ... }`, `experiment \"name\" { ... }`, `train N { ... }`, `repeat N { ... }`, `if c { ... } else { ... }`; \
37	define a function with `def u:name(a, b) { body }` -- the `u:` prefix is REQUIRED and there is NO `return` (the block's last expression is its value) -- then call it `u:name(args)`; iterate with `for x in iota(n) { ... }` or `while cond { ... }`; index/slice a tensor with `take(x, axis, i)`. \
38	Statements inside a block are separated by `;`. The COMPLETE builtin set follows (call ONLY these exact signatures -- there is no filter/map/print/length/strcat/append):";
39	
40	/// The compact MLPL reference for the `:ask` system prompt: the syntax
41	/// cheat-sheet plus every builtin's signature, grouped, sourced from the
42	/// curated `BUILTIN_GROUPS` table so it never drifts from the real set.
43	fn mlpl_reference() -> String {
44	    let mut r = MLPL_SYNTAX.to_string();
45	    for (group, entries) in mlpl_eval_core::inspect_groups::BUILTIN_GROUPS {
46	        let sigs: Vec<&str> = entries.iter().map(|&(_, sig, _)| sig).collect();
47	        r.push_str(&format!(" [{group}] {}.", sigs.join(", ")));
48	    }
49	    r
50	}
51	
52	/// Read a URL query parameter, falling back to `default` when it
53	/// is absent or empty. (`name` is a fixed literal, never user
54	/// input, so the inlined script is safe.)
55	fn query_param(name: &str, default: &str) -> String {
56	    let script = format!("new URLSearchParams(location.search).get('{name}') || ''");
57	    js_sys::eval(&script)
58	        .ok()
59	        .and_then(|v| v.as_string())
60	        .filter(|s| !s.is_empty())
61	        .unwrap_or_else(|| default.to_string())
62	}
63	
64	/// Plain-text summary of the sculpture the user is currently
65	/// inspecting (via the `window.__stage3d_context()` JS hook), or
66	/// empty when nothing is selected.
67	fn selection_context() -> String {
68	    js_sys::eval("window.__stage3d_context ? window.__stage3d_context() : ''")
69	        .ok()
70	        .and_then(|v| v.as_string())
71	        .unwrap_or_default()
72	}
73	
74	/// Summarize the recent REPL activity (last few command/result
75	/// pairs) so `:ask` can answer questions about "what is being run
76	/// in the REPL" -- an in-context REPL assistant. Newest entries
77	/// are kept; long outputs are truncated char-safely.
78	fn repl_history_context(history: &[HistoryEntry]) -> String {
79	    let mut recent: Vec<String> = history
80	        .iter()
81	        .rev()
82	        .filter(|e| matches!(e.kind, EntryKind::Command))
83	        .take(6)
84	        .map(|e| {
85	            let out: String = e.output.trim().chars().take(180).collect();
86	            format!("mlpl> {} => {}", e.input.trim(), out)
87	        })
88	        .collect();
89	    recent.reverse();
90	    recent.join(" | ")
91	}
92	
93	/// Build the `:ask` system message: meta preamble + recent REPL
94	/// activity + the selected sculpture (if any). This goes in
95	/// Ollama's `system` role (not the prompt), which weak models
96	/// follow far better. The question is sent as the user prompt.
97	fn build_ask_system(history: &[HistoryEntry]) -> String {
98	    let mut p = ASK_SYSTEM.to_string();
99	    // Compact MLPL reference (syntax + builtin signatures) -- real forms.
100	    p.push_str(&mlpl_reference());
101	    // Ground the model in the active demo (its "About this demo -- <name>"
102	    // narration names the task, e.g. tic-tac-toe) so it doesn't guess Othello.
103	    if let Some(intro) = history
104	        .iter()
105	        .rev()
106	        .find(|e| matches!(e.kind, EntryKind::Narration) && e.input.starts_with("About this demo"))
107	    {
108	        let body: String = intro.output.trim().chars().take(400).collect();
109	        p.push_str(&format!(" Active demo -- {}: {body}.", intro.input.trim()));
110	    }
111	    let recent = repl_history_context(history);
112	    if !recent.is_empty() {
113	        p.push_str(&format!(" Recent REPL activity (oldest first): {recent}."));
114	    }
115	    let sel = selection_context();
116	    if !sel.is_empty() {
117	        p.push_str(&format!(" Selected 3D sculpture: {sel}."));
118	    }
119	    p
120	}
121	
122	/// Map a submitted line to the program to send to the server.
123	/// `:ask <question>` becomes a 4-arg `llm_call` -- the question is
124	/// the user prompt and the grounding/context rides in the `system`
125	/// field. A bare expression passes through; any other slash-command
126	/// returns `None` to stay local.
127	fn connect_program(line: &str, history: &[HistoryEntry]) -> Option<String> {
128	    let t = line.trim_start();
129	    if let Some(q) = t.strip_prefix(":ask ") {
130	        let esc = |s: &str| s.replace('\\', "\\\\").replace('"', "\\\"");
131	        let question = esc(q.trim().trim_matches('"').trim());
132	        let system = esc(&build_ask_system(history));
133	        let (url, model) = ask_endpoint();
134	        return Some(format!(
135	            "llm_call(\"{url}\", \"{question}\", \"{model}\", \"{system}\")"
136	        ));
137	    }
138	    if t.starts_with(':') {
139	        return None;
140	    }
141	    Some(line.to_string())
142	}
143	
144	/// Set up the telemetry trace for the eval about to run. It is `remote`
145	/// (live panel shown) only when connected AND the line is a server
146	/// -routed program (a bare expression or `:ask`); browser-local evals
147	/// `begin(false)` so the panel stays hidden for a computation that runs
148	/// in the browser, not on the server.
149	pub(crate) fn begin_eval_telemetry(line: &str, history: &[HistoryEntry]) {
150	    let remote = mlpl_web_eval::eval::current_connect_url_from_window().is_some()
151	        && connect_program(line, history).is_some();
152	    mlpl_web_eval::telemetry_trace::begin(remote);
153	}
154	
155	/// Route one demo line through the connected server (connect mode):
156	/// the `:connect list` listing, the `:ask` shortcut, or a bare
157	/// expression. Fires `on_result` with the display string when the
158	/// server responds. Returns true when it took the line; false for a
159	/// non-eligible `:` command so the demo runner falls back to local
160	/// eval. Shared by the demo runner so loaded demos behave like
161	/// typed lines in connect mode.
162	pub(crate) fn dispatch_demo_line(
163	    line: &str,
164	    history: &[HistoryEntry],
165	    route_all: bool,
166	    on_result: mlpl_web_eval::eval::ResultCb,
167	) -> bool {
168	    // Demo lines carry trailing `# comment` annotations. Strip them only
169	    // for matching `:status` / `:connect list` (so `:connect list # ...`
170	    // is not read as a host and `:status # ...` matches). `:ask` and plain
171	    // MLPL lines keep the ORIGINAL `line`: `:ask` sends its prompt to
172	    // Ollama verbatim (a `#` is part of the question, not a comment), and
173	    // a plain MLPL line may carry a `#` inside a string literal.
174	    let cmd_line = line.split('#').next().unwrap_or(line);
175	    let t = cmd_line.trim();
176	    if t == ":status" {
177	        let Some(base) = mlpl_web_eval::eval::current_connect_url_from_window() else {
178	            return false;
179	        };
180	        let ready = mlpl_web_eval::ollama_fetch::ollama_default().is_some();
181	        mlpl_web_eval::stats_fetch::fetch_status(base, ready, on_result);
182	        return true;
183	    }
184	    if t == ":connect list" || t.starts_with(":connect list ") {
185	        let host = t
186	            .strip_prefix(":connect list ")
187	            .map(|h| h.trim().to_string());
188	        let Some(base) = mlpl_web_eval::eval::current_connect_url_from_window() else {
189	            return false;
190	        };
191	        mlpl_web_eval::ollama_fetch::fetch_ollama_models(base, host, on_result);
192	        return true;
193	    }
194	    if t.starts_with(":ask ") {
195	        // Verbatim: the whole prompt (including any `#`) goes to Ollama.
196	        if let Some(program) = connect_program(line, history) {
197	            return mlpl_web_eval::eval_wasm::connect_eval(&program, on_result);
198	        }
199	    }
200	    // `route_all` is set for connect-only demos (MLX/CUDA tier):
201	    // their heavy training runs server-side so the browser main
202	    // thread stays responsive (and uses the GPU). CPU-tier demos
203	    // pass `route_all=false`, so plain MLPL lines stay LOCAL and keep
204	    // emitting 3D viz (the connect path returns only a display
205	    // string). Full 3D for server-routed lines arrives with the
206	    // viz-passthrough step.
207	    if route_all && !t.starts_with(':') {
208	        return mlpl_web_eval::eval_wasm::connect_eval(line, on_result);
209	    }
210	    false
211	}
212	
213	/// Resolve the `(host, model)` for `:ask`. Host: `?ollama=` page
214	/// override, else the connect-primed default, else the constant. Model:
215	/// a `:connect set <model>` session pick wins, then `?model=`, then the
216	/// connect-primed default, then the constant.
217	fn ask_endpoint() -> (String, String) {
218	    let (def_url, def_model) = mlpl_web_eval::ollama_fetch::ollama_default()
219	        .unwrap_or_else(|| (ASK_URL.to_string(), ASK_MODEL.to_string()));
220	    let model = mlpl_web_eval::ollama_fetch::selected_model()
221	        .unwrap_or_else(|| query_param("model", &def_model));
222	    (query_param("ollama", &def_url), model)
223	}
224	
225	/// Connect-mode `:connect list` (and bare `:connect`, which aliases to
226	/// it when connected): fetch the server's Ollama model list (`GET
227	/// /v1/ollama/tags`) and render it as a history entry, chaining the rest
228	/// of the queue. Returns true when it took the line (connect mode + the
229	/// command); false to fall through to local handling -- so when NOT
230	/// connected, bare `:connect` still reaches the "needs a server" message.
231	pub(crate) fn try_ollama_models(
232	    deps: &EvalDeps,
233	    history: &[HistoryEntry],
234	    queue: &[String],
235	    idx: usize,
236	    line: &str,
237	) -> bool {
238	    let t = line.trim();
239	    if t != ":connect" && t != ":connect list" && !t.starts_with(":connect list ") {
240	        return false;
241	    }
242	    let host = t
243	        .strip_prefix(":connect list ")
244	        .map(|h| h.trim().to_string());
245	    let Some(base) = mlpl_web_eval::eval::current_connect_url_from_window() else {
246	        return false;
247	    };
248	    let hist_handle = deps.history.clone();
249	    let deps_c = deps.clone();
250	    let queue_c = queue.to_vec();
251	    let line_in = t.to_string();
252	    let mut hist_c = history.to_vec();
253	    mlpl_web_eval::ollama_fetch::fetch_ollama_models(
254	        base,
255	        host,
256	        Box::new(move |result: String| {
257	            let is_error = result.starts_with("error:");
258	            hist_c.pop();
259	            hist_c.push(HistoryEntry {
260	                input: line_in,
261	                output: result,
262	                is_error,
263	                kind: EntryKind::Command,
264	            });
265	            hist_handle.set(hist_c.clone());
266	            crate::submit::process_next_eval(deps_c, hist_c, queue_c, idx + 1);
267	        }),
268	    );
269	    true
270	}
271	
272	/// Connect-mode `:status`: probe the server's `/v1/devices` +
273	/// `/v1/stats` and render a self-test report (devices, live
274	/// CPU/RAM/GPU/VRAM, Ollama state) as a history entry, chaining the
275	/// rest of the queue. Returns true when it took the line (connect mode
276	/// + the exact command); false to fall through to the local handler.
277	pub(crate) fn try_status(
278	    deps: &EvalDeps,
279	    history: &[HistoryEntry],
280	    queue: &[String],
281	    idx: usize,
282	    line: &str,
283	) -> bool {
284	    let t = line.trim();
285	    if t != ":status" && t != ":status watch" {
286	        return false;
287	    }
288	    let Some(base) = mlpl_web_eval::eval::current_connect_url_from_window() else {
289	        return false;
290	    };
291	    let hist_handle = deps.history.clone();
292	    let deps_c = deps.clone();
293	    let queue_c = queue.to_vec();
294	    let input = t.to_string();
295	    let mut hist_c = history.to_vec();
296	    let cb: mlpl_web_eval::eval::ResultCb = Box::new(move |result: String| {
297	        let is_error = result.starts_with("error:");
298	        hist_c.pop();
299	        hist_c.push(HistoryEntry {
300	            input: input.clone(),
301	            output: result,
302	            is_error,
303	            kind: EntryKind::Command,
304	        });
305	        hist_handle.set(hist_c.clone());
306	        crate::submit::process_next_eval(deps_c, hist_c, queue_c, idx + 1);
307	    });
308	    if t == ":status watch" {
309	        // bounded burst (~12 samples, ~3.6s) -> persisted sparkline
310	        mlpl_web_eval::telemetry_trace::watch(base, 12, cb);
311	    } else {
312	        let ollama_ready = mlpl_web_eval::ollama_fetch::ollama_default().is_some();
313	        mlpl_web_eval::stats_fetch::fetch_status(base, ollama_ready, cb);
314	    }
315	    true
316	}
317	
318	/// Synchronously replace the trailing running-marker with a finished
319	/// command entry and chain the rest of the queue. For connect commands
320	/// that resolve without a fetch (the `:reset` prompt and its abort).
321	fn chain_entry(
322	    deps: &EvalDeps,
323	    history: &[HistoryEntry],
324	    queue: &[String],
325	    idx: usize,
326	    entry: (&str, &str, bool),
327	) {
328	    let (input, output, is_error) = entry;
329	    let mut hist_c = history.to_vec();
330	    hist_c.pop();
331	    hist_c.push(HistoryEntry {
332	        input: input.to_string(),
333	        output: output.to_string(),
334	        is_error,
335	        kind: EntryKind::Command,
336	    });
337	    deps.history.set(hist_c.clone());
338	    crate::submit::process_next_eval(deps.clone(), hist_c, queue.to_vec(), idx + 1);
339	}
340	
341	/// Connect-mode `:reset` (step 1 of 2): ARM the confirmation and print a
342	/// (y/N) prompt. `:reset` cancels ALL in-flight work on the backend, so
343	/// it never fires on a stray keystroke -- the POST happens only if the
344	/// next line confirms (`try_reset_answer`). Returns false in local mode
345	/// so the "nothing to reset" handler runs instead.
346	pub(crate) fn try_reset(
347	    deps: &EvalDeps,
348	    history: &[HistoryEntry],
349	    queue: &[String],
350	    idx: usize,
351	    line: &str,
352	) -> bool {
353	    if line.trim() != ":reset" || mlpl_web_eval::eval::current_connect_url_from_window().is_none() {
354	        return false;
355	    }
356	    mlpl_web_eval::stats_fetch::arm_reset();
357	    let prompt = "Cancel ALL in-flight work on the connected backend? This aborts every \
358	                  running eval / training loop. Type `y` (or `yes`) to confirm; \
359	                  anything else aborts.  (y/N)";
360	    chain_entry(deps, history, queue, idx, (":reset", prompt, false));
361	    true
362	}
363	
364	/// Consume a pending `:reset` confirmation. Runs FIRST in the dispatch
365	/// chain but only acts when `:reset` was armed on the previous line:
366	/// `y`/`yes` -> POST /v1/reset; anything else -> abort, no changes.
367	/// Returns true when it consumed the line.
368	pub(crate) fn try_reset_answer(
369	    deps: &EvalDeps,
370	    history: &[HistoryEntry],
371	    queue: &[String],
372	    idx: usize,
373	    line: &str,
374	) -> bool {
375	    if !mlpl_web_eval::stats_fetch::take_reset_armed() {
376	        return false;
377	    }
378	    let ans = line.trim().to_ascii_lowercase();
379	    if ans == "y" || ans == "yes" {
380	        post_reset(deps, history, queue, idx);
381	    } else {
382	        chain_entry(
383	            deps,
384	            history,
385	            queue,
386	            idx,
387	            (line, "reset aborted -- no changes.", false),
388	        );
389	    }
390	    true
391	}
392	
393	/// POST `/v1/reset` (confirmed): cancel all in-flight evals on the
394	/// server, render the cancel count, and chain the queue.
395	fn post_reset(deps: &EvalDeps, history: &[HistoryEntry], queue: &[String], idx: usize) {
396	    let Some(base) = mlpl_web_eval::eval::current_connect_url_from_window() else {
397	        chain_entry(
398	            deps,
399	            history,
400	            queue,
401	            idx,
402	            (":reset", "error: not connected", true),
403	        );
404	        return;
405	    };
406	    let hist_handle = deps.history.clone();
407	    let deps_c = deps.clone();
408	    let queue_c = queue.to_vec();
409	    let mut hist_c = history.to_vec();
410	    mlpl_web_eval::stats_fetch::fetch_reset(
411	        base,
412	        Box::new(move |result: String| {
413	            let is_error = result.starts_with("error:");
414	            hist_c.pop();
415	            hist_c.push(HistoryEntry {
416	                input: ":reset".to_string(),
417	                output: result,
418	                is_error,
419	                kind: EntryKind::Command,
420	            });
421	            hist_handle.set(hist_c.clone());
422	            crate::submit::process_next_eval(deps_c, hist_c, queue_c, idx + 1);
423	        }),
424	    );
425	}
426	
427	/// Dispatch `line` to the connected server (async) when a connect
428	/// URL is set and the line is server-eligible, chaining the rest
429	/// of the queue in the result callback so line order is kept.
430	/// Returns true when it took the eval; false to let the caller
431	/// evaluate locally.
432	pub(crate) fn try_connect_eval(
433	    deps: &EvalDeps,
434	    history: &[HistoryEntry],
435	    queue: &[String],
436	    idx: usize,
437	    line: &str,
438	) -> bool {
439	    let Some(program) = connect_program(line, history) else {
440	        return false;
441	    };
442	    let hist_handle = deps.history.clone();
443	    let deps_c = deps.clone();
444	    let queue_c = queue.to_vec();
445	    let line_c = line.to_string();
446	    let mut hist_c = history.to_vec();
447	    // Capture THIS eval's telemetry generation now (synchronous with its
448	    // begin()); read only that gen_id's sparkline when the result lands, so
449	    // a concurrent watch/eval can't intermix.
450	    let gen_id = mlpl_web_eval::telemetry_trace::current_gen();
451	    mlpl_web_eval::eval_wasm::connect_eval(
452	        &program,
453	        Box::new(move |result: String| {
454	            let is_error = result.starts_with("error:");
455	            // Persist the backend-load sparkline collected by the live
456	            // panel so the trace (incl. a brief GPU blip) survives the
457	            // marker being replaced. Only when samples were collected.
458	            let output = match (is_error, mlpl_web_eval::telemetry_trace::summary(gen_id)) {
459	                (false, Some(tel)) => format!("{result}\n{tel}"),
460	                _ => result,
461	            };
462	            hist_c.pop();
463	            hist_c.push(HistoryEntry {
464	                input: line_c.clone(),
465	                output,
466	                is_error,
467	                kind: EntryKind::Command,
468	            });
469	            hist_handle.set(hist_c.clone());
470	            crate::submit::process_next_eval(deps_c, hist_c, queue_c, idx + 1);
471	        }),
472	    )
473	}
