8	/// Single-line submit: thin wrapper that pipes the line through
9	/// the batch path so there is exactly one place that mutates
10	/// state. Calling `make_submit` N times in a tight loop USED
11	/// to drop N-1 history entries because each call did
12	/// `(*deps.history).clone()` -> push one -> `set(new)` --
13	/// inside one event tick every clone read the same snapshot
14	/// and only the last `set` won (Tutorial Run-All bug, May 7
15	/// 2026). Routing through `make_submit_batch` collapses any
16	/// number of lines into a single read-modify-write.
17	pub fn make_submit(deps: EvalDeps) -> Callback<String> {
18	    let batch = make_submit_batch(deps);
19	    Callback::from(move |line: String| batch.emit(vec![line]))
20	}
21	
22	/// Evaluate every line in `lines` against the current session
23	/// in one pass, then commit all four state handles exactly
24	/// once. Empty/whitespace-only lines are skipped (matching
25	/// single-line submit semantics); `:clear` and `:help` are
26	/// honored mid-batch.
27	pub fn make_submit_batch(deps: EvalDeps) -> Callback<Vec<String>> {
28	    Callback::from(move |lines: Vec<String>| {
29	        let mut new_history = (*deps.history).clone();
30	        let mut new_cmds = (*deps.cmd_history).clone();
31	        let mut eval_queue: Vec<String> = Vec::new();
32	        for line in lines {
33	            classify_line(
34	                &deps,
35	                line,
36	                &mut new_history,
37	                &mut new_cmds,
38	                &mut eval_queue,
39	            );
40	        }
41	        if new_cmds.is_empty() {
42	            return;
43	        }
44	        deps.cmd_history.set(new_cmds);
45	        deps.cmd_index.set(None);
46	        deps.input_value.set(String::new());
47	        if eval_queue.is_empty() {
48	            deps.history.set(new_history);
49	            return;
50	        }
51	        process_next_eval(deps.clone(), new_history, eval_queue, 0);
52	    })
53	}
54	
55	/// Classify one submitted line: `:clear` / `:3d ...` / upload commands
56	/// run immediately; everything else is queued for the WASM evaluator.
57	fn classify_line(
58	    deps: &EvalDeps,
59	    line: String,
60	    new_history: &mut Vec<HistoryEntry>,
61	    new_cmds: &mut Vec<String>,
62	    eval_queue: &mut Vec<String>,
63	) {
64	    let trimmed = line.trim();
65	    if trimmed.is_empty() {
66	        return;
67	    }
68	    new_cmds.push(trimmed.to_string());
69	    // `:<cmd> --help` is REPL command help (vs bare args = command
70	    // input). Intercept it here so it works in both connect + local mode
71	    // and never routes to the server / Ollama.
72	    if let Some(help) = crate::help::command_help(trimmed) {
73	        new_history.push(HistoryEntry {
74	            input: trimmed.to_string(),
75	            output: help,
76	            is_error: false,
77	            kind: EntryKind::Command,
78	        });
79	        return;
80	    }
81	    if trimmed == ":clear" {
82	        deps.session.borrow().clear();
83	        new_history.clear();
84	        if *deps.show_3d {
85	            let _ = js_sys::eval("window.__stage3d_clear && window.__stage3d_clear()");
86	        }
87	        return;
88	    }
89	    if let Some(cmd) = mlpl_web_viz3d::toggle::parse_3d_command(trimmed) {
90	        apply_3d_command(deps, cmd);
91	        return;
92	    }
93	    if let Some(name) = parse_upload_command(trimmed) {
94	        new_history.push(handle_upload_command(deps, trimmed, &name));
95	        return;
96	    }
97	    eval_queue.push(trimmed.to_string());
98	}
