100	fn apply_3d_command(deps: &EvalDeps, cmd: mlpl_web_viz3d::toggle::Viz3dCmd) {
101	    match cmd {
102	        mlpl_web_viz3d::toggle::Viz3dCmd::On => deps.show_3d.set(true),
103	        mlpl_web_viz3d::toggle::Viz3dCmd::Off => deps.show_3d.set(false),
104	        mlpl_web_viz3d::toggle::Viz3dCmd::Reset => {
105	            let _ = js_sys::eval("window.__stage3d_reset_view && window.__stage3d_reset_view()");
106	        }
107	    }
108	}
