168	/// Saga 29 step 018: human-readable "this line is running"
169	/// caption tailored to the kind of line. Train blocks call out
170	/// the expected duration; everything else gets a generic
171	/// "evaluating..." marker that still tells the user the demo
172	/// hasn't hung. Saga 33 step 027: a "train 5"-shaped chunk
173	/// gets a chunk-sized caption so the user understands each
174	/// chunk is short and the page will recover between chunks;
175	/// large `train 30`+ blocks keep the long-duration warning.
176	pub(crate) fn running_message(line: &str) -> &'static str {
177	    let stripped = line.trim_start();
178	    if stripped.starts_with("train ") || stripped.starts_with("train{") {
179	        return crate::running::train_caption(stripped);
180	    }
181	    if stripped.starts_with("repeat ") {
182	        "looping... (this can take a few seconds)"
183	    } else if stripped.contains("predict_batch")
184	        || stripped.contains("apply(")
185	        || stripped.contains("attention_weights")
186	    {
187	        "evaluating... (forward pass through the trained model)"
188	    } else if stripped.contains("svg(") {
189	        "rendering visualization..."
190	    } else {
191	        "evaluating..."
192	    }
193	}
