//! Whether connect mode can actually reach the server from THIS page.
//!
//! The public demo is served over HTTPS. A `?connect=http://...` to a
//! non-local server is blocked by the browser (mixed content: an https://
//! page may not fetch a plain http:// origin), and a cross-origin server
//! also needs CORS. When that's the case the UI should treat the page as
//! NOT connected -- disable connect demos, keep the button on "Connect",
//! and explain the block -- rather than claim "Connected" and then fail
//! every request with a cryptic "Failed to fetch".

/// Only the wasm `connect_blocked_reason` consumes this; native builds
/// never reach it, so gate the const to avoid a dead-code warning there.
#[cfg(target_arch = "wasm32")]
const MIXED_CONTENT_MSG: &str = "Connect mode is unavailable from the public HTTPS demo. \
Browsers block requests from an https:// page to a plain http:// server (mixed content), and a \
cross-origin server also needs CORS. To use connect mode, open the playground from the server \
itself -- http://<host>:6464/sw-mlpl -- or, on the same machine, append \
?connect=http://127.0.0.1:6464.";

/// The pure mixed-content rule, testable without a browser: an https page
/// cannot reach a plain-http, non-local connect server. `localhost` /
/// `127.0.0.1` are exempt -- browsers treat them as potentially trustworthy.
#[must_use]
pub fn is_mixed_content_blocked(page_is_https: bool, connect_url: &str) -> bool {
    let local = connect_url.contains("localhost")
        || connect_url.contains("127.0.0.1")
        || connect_url.contains("[::1]");
    page_is_https && connect_url.starts_with("http://") && !local
}

/// The user-facing reason connect mode is blocked from this page, or `None`
/// when it should work (same-scheme page/server, or a localhost URL, or no
/// `?connect=` at all).
#[cfg(target_arch = "wasm32")]
#[must_use]
pub fn connect_blocked_reason() -> Option<String> {
    let url = crate::eval_url::current_connect_url_from_window()?;
    let https = web_sys::window()?.location().protocol().ok().as_deref() == Some("https:");
    is_mixed_content_blocked(https, &url).then(|| MIXED_CONTENT_MSG.to_string())
}

/// Native builds have no browser and no connect URL, so nothing is blocked.
#[cfg(not(target_arch = "wasm32"))]
#[must_use]
pub fn connect_blocked_reason() -> Option<String> {
    None
}

//! Connect-telemetry step 002: per-eval live-loss series store.
//!
//! `loss_trace` mirrors `telemetry_trace`'s generation model but holds
//! streamed `*_metric` training series instead of hardware samples, and
//! is NOT wasm-gated so the reducer logic tests natively.

use mlpl_web_eval::loss_trace;

// Generations in these tests are arbitrary but unique per test so the
// shared thread-local store never cross-talks (tests may share a thread).

#[test]
fn push_builds_a_train_series_in_arrival_order() {
    let gen_id = 9001;
    loss_trace::push(gen_id, "loss_metric", 3.0);
    loss_trace::push(gen_id, "loss_metric", 2.0);
    loss_trace::push(gen_id, "loss_metric", 1.0);
    let (train, val) = loss_trace::series(gen_id);
    assert_eq!(train, vec![3.0, 2.0, 1.0]);
    assert!(val.is_empty());
}

#[test]
fn val_prefixed_metric_lands_in_the_val_series() {
    let gen_id = 9002;
    loss_trace::push(gen_id, "loss_metric", 3.0);
    loss_trace::push(gen_id, "val_loss_metric", 4.0);
    loss_trace::push(gen_id, "loss_metric", 2.0);
    loss_trace::push(gen_id, "val_loss_metric", 3.5);
    let (train, val) = loss_trace::series(gen_id);
    assert_eq!(train, vec![3.0, 2.0]);
    assert_eq!(val, vec![4.0, 3.5]);
}

#[test]
fn non_loss_metric_still_charts_as_the_primary_series() {
    let gen_id = 9003;
    loss_trace::push(gen_id, "acc_metric", 0.5);
    loss_trace::push(gen_id, "acc_metric", 0.75);
    let (train, val) = loss_trace::series(gen_id);
    assert_eq!(train, vec![0.5, 0.75]);
    assert!(val.is_empty());
}

#[test]
fn generations_stay_isolated() {
    loss_trace::push(9004, "loss_metric", 1.0);
    loss_trace::push(9005, "loss_metric", 9.0);
    let (a, _) = loss_trace::series(9004);
    let (b, _) = loss_trace::series(9005);
    assert_eq!(a, vec![1.0]);
    assert_eq!(b, vec![9.0]);
}

#[test]
fn seq_increments_per_push_and_reads_zero_for_unknown() {
    let gen_id = 9006;
    assert_eq!(loss_trace::seq(gen_id), 0);
    loss_trace::push(gen_id, "loss_metric", 1.0);
    loss_trace::push(gen_id, "val_loss_metric", 2.0);
    assert_eq!(loss_trace::seq(gen_id), 2);
}

#[test]
fn summary_consumes_and_names_final_loss() {
    let gen_id = 9007;
    loss_trace::push(gen_id, "loss_metric", 4.0);
    loss_trace::push(gen_id, "loss_metric", 0.125);
    let s = loss_trace::summary(gen_id).expect("summary for populated gen");
    assert!(s.contains("loss"), "summary names the series: {s}");
    assert!(s.contains("0.125"), "summary shows final value: {s}");
    assert!(s.contains('2'), "summary shows step count: {s}");
    assert!(loss_trace::summary(gen_id).is_none(), "summary consumes");
}

#[test]
fn summary_is_none_for_empty_or_unknown_gen() {
    assert!(loss_trace::summary(424_242).is_none());
}

#[test]
fn train_programs_stream_metrics_other_programs_do_not() {
    assert!(loss_trace::program_streams_metrics(
        "train 5 { loss_metric = step ; step }"
    ));
    assert!(loss_trace::program_streams_metrics(
        "x = 1 ; train 30 {\n  loss_metric = l\n}"
    ));
    assert!(!loss_trace::program_streams_metrics("x = iota(5) + 1"));
    assert!(!loss_trace::program_streams_metrics(":ask how do I train?"));
    // The `:ask` shortcut becomes an llm_call program -- the word
    // "train" inside the question must not route it to the stream path.
    assert!(!loss_trace::program_streams_metrics(
        "llm_call(\"http://x\", \"how does train 5 { } work?\", \"m\", \"s\")"
    ));
    // "train" as a substring of an identifier is not a train block.
    assert!(!loss_trace::program_streams_metrics("retrain_flag = 1"));
    assert!(!loss_trace::program_streams_metrics("trainx = { }"));
}

