use std::cell::RefCell;
use std::rc::Rc;

use mlpl_wasm::WasmSession;
use yew::prelude::*;

use crate::running::{push_running_marker, replace_running_with_result};
use mlpl_web_demos::DEMOS;
use mlpl_web_eval::state::{EntryKind, HistoryEntry};

pub fn make_run_demo(
    session: Rc<RefCell<WasmSession>>,
    history: UseStateHandle<Vec<HistoryEntry>>,
) -> Callback<usize> {
    Callback::from(move |idx: usize| {
        let Some(demo) = DEMOS.get(idx) else {
            return;
        };
        session.borrow().clear();
        let _ = js_sys::eval("window.__stage3d_clear && window.__stage3d_clear()");
        // Lead with a narration panel framing what the demo does
        // and why. Demo lines follow; the takeaway narration lands
        // after the final line in `schedule_demo_line`. Also bind
        // a `_demo` string in the session so `:describe _demo`
        // prints the intro + takeaway from the REPL.
        bind_demo_metadata(&session.borrow(), demo);
        let intro_entry = HistoryEntry {
            input: format!("About this demo -- {}", demo.name),
            output: intro_with_literate_link(demo),
            is_error: false,
            kind: EntryKind::Narration,
        };
        let entries = vec![intro_entry];
        history.set(entries.clone());
        // Evaluate demo lines asynchronously: each line runs in
        // its own `Timeout::new(0, ...)` tick so the browser can
        // paint the preceding line's output and process input
        // between lines. A long-running single line (e.g. `train
        // 30 { ... }`) still blocks the event loop *during* its
        // own eval -- fixing that needs Web Workers (see
        // docs/worker-threads.md) -- but the cross-line yield
        // keeps the tab from triggering the "unresponsive"
        // dialog on multi-line demos where the total wall clock
        // is the problem.
        //
        // We thread the accumulated `entries` vec through
        // recursion explicitly rather than reading from the
        // `UseStateHandle` inside each tick: a state handle is
        // snapshotted at the callback's closure-creation time
        // and does not refresh between `set()` calls, so reading
        // via `(*history).clone()` inside a deferred Timeout
        // reliably sees the stale initial value and each tick
        // overwrites the previous one's write. Passing `entries`
        // by move keeps a single authoritative Rust-side source
        // of truth; `history.set(entries.clone())` is purely for
        // the UI paint.
        schedule_demo_line(session.clone(), history.clone(), entries, demo, 0);
    })
}

/// The demo intro, with a "literate walkthrough" link appended when
/// the demo has a companion org-mode HTML (bundled under `literate/`).
/// For connect-only demos the link is the way to see what the demo
/// does without a server -- the page is a real recorded run.
fn intro_with_literate_link(demo: &mlpl_web_demos::Demo) -> String {
    match mlpl_web_demos::literate_for(demo.name) {
        Some(file) => format!(
            "{}\n\n[Emacs Org-mode literate walkthrough](literate/{file}) -- every step run and explained, with the before/after chart.",
            demo.intro
        ),
        None => demo.intro.to_string(),
    }
}

/// Bind `_demo` as a string variable in the session so typing
/// `:describe _demo` after a demo run reprints the intro +
/// takeaway. Uses MLPL's string-assignment syntax through `eval`
/// so the binding goes through the existing string-variable
/// surface (Saga 12 step 009) -- no new plumbing.
fn bind_demo_metadata(session: &WasmSession, demo: &mlpl_web_demos::Demo) {
    let body = format!(
        "{}\n\nAbout this demo:\n  {}\n\nTakeaway:\n  {}",
        demo.name, demo.intro, demo.takeaway,
    );
    let escaped = body.replace('\\', "\\\\").replace('"', "\\\"");
    let _ = session.eval(&format!("_demo = \"{escaped}\""));
}

fn push_progress_notes(entries: &mut Vec<HistoryEntry>, demo_name: &str, idx: usize) -> bool {
    let mut had = false;
    for note in mlpl_web_demos::progress_notes_for(demo_name, idx) {
        entries.push(HistoryEntry {
            input: note.heading.to_string(),
            output: note.body.to_string(),
            is_error: false,
            kind: EntryKind::Narration,
        });
        had = true;
    }
    had
}

fn schedule_demo_line(
    session: Rc<RefCell<WasmSession>>,
    history: UseStateHandle<Vec<HistoryEntry>>,
    mut entries: Vec<HistoryEntry>,
    demo: &'static mlpl_web_demos::Demo,
    idx: usize,
) {
    let lines = demo.lines;
    if idx >= lines.len() {
        // Last line ran -- append the takeaway narration panel
        // and paint the final history state.
        entries.push(HistoryEntry {
            input: "What just happened".to_string(),
            output: demo.takeaway.to_string(),
            is_error: false,
            kind: EntryKind::Narration,
        });
        history.set(entries);
        return;
    }
    push_progress_notes(&mut entries, demo.name, idx);
    let line = lines[idx];
    // Telemetry panel only for SERVER-side lines (browser free to sample):
    // MLX/CUDA compute lines, or any `:ask` (LLM runs server-side). Local
    // evals block the sampler -> no panel (see docs/worker-threads.md).
    #[cfg(target_arch = "wasm32")]
    {
        let lt = line.trim_start();
        let server_side = mlpl_web_eval::eval_url::is_connected()
            && (lt.starts_with(":ask")
                || (mlpl_web_demos::capability_for(demo.name).requires_connect
                    && !lt.starts_with(':')));
        mlpl_web_eval::telemetry_trace::begin(server_side);
    }
    push_running_marker(&mut entries, line);
    history.set(entries.clone());
    // Connect mode: route the line through the server (so loaded
    // demos behave like typed lines -- `:connect list`, `:ask`,
    // and bare expressions hit mlpl-serve instead of the local
    // session). Falls through to local eval when not connected or
    // for non-eligible commands.
    #[cfg(target_arch = "wasm32")]
    if mlpl_web_eval::eval_url::is_connected()
        && dispatch_demo_line_connected(&session, &history, &entries, demo, idx, line)
    {
        return;
    }
    run_demo_line_local(session, history, entries, demo, idx, line);
}

/// Evaluate one demo line in the local in-process WASM session
/// (the non-connect path), in its own `Timeout` tick so the
/// browser paints between lines, then recurse to the next line.
fn run_demo_line_local(
    session: Rc<RefCell<WasmSession>>,
    history: UseStateHandle<Vec<HistoryEntry>>,
    mut entries: Vec<HistoryEntry>,
    demo: &'static mlpl_web_demos::Demo,
    idx: usize,
    line: &'static str,
) {
    let session_next = Rc::clone(&session);
    let history_next = history.clone();
    gloo::timers::callback::Timeout::new(0, move || {
        let r = session.borrow().eval_with_values(line);
        let is_error = r.display.starts_with("error:");
        if !is_error {
            let name = line.split('=').next().unwrap_or(line).trim().to_string();
            let info = mlpl_web_viz3d::events::build_shape_info_full(
                name,
                r.shape,
                r.values,
                r.string_list,
                r.viz_node,
            );
            mlpl_web_viz3d::events::emit(&mlpl_web_viz3d::events::Stage3dEvent {
                step_idx: 0,
                label: mlpl_eval_core::indent_source(line),
                output: info,
            });
        }
        replace_running_with_result(&mut entries, line, r.display);
        history.set(entries.clone());
        schedule_demo_line(session_next, history_next, entries, demo, idx + 1);
    })
    .forget();
}

/// Connect-mode demo line: dispatch to the server and continue the
/// demo when the async result lands. Returns false (caller does
/// local eval) for lines the server path does not handle.
#[cfg(target_arch = "wasm32")]
fn dispatch_demo_line_connected(
    session: &Rc<RefCell<WasmSession>>,
    history: &UseStateHandle<Vec<HistoryEntry>>,
    entries: &[HistoryEntry],
    demo: &'static mlpl_web_demos::Demo,
    idx: usize,
    line: &'static str,
) -> bool {
    let mut entries_c = entries.to_vec();
    let hist = history.clone();
    let sess = Rc::clone(session);
    // This demo line's telemetry generation (begin()'d before its marker).
    let gen_id = mlpl_web_eval::telemetry_trace::current_gen();
    let cont: mlpl_web_eval::eval::ResultCb = Box::new(move |display: String| {
        // Persist the backend-load sparkline below a server-run demo line
        // so a brief GPU blip survives the marker being replaced.
        let out = match (
            display.starts_with("error:"),
            mlpl_web_eval::telemetry_trace::summary(gen_id),
        ) {
            (false, Some(tel)) => format!("{display}\n{tel}"),
            _ => display,
        };
        replace_running_with_result(&mut entries_c, line, out);
        hist.set(entries_c.clone());
        schedule_demo_line(sess, hist.clone(), entries_c, demo, idx + 1);
    });
    // Connect-only demos (MLX/CUDA tier) run their heavy lines on the
    // server so the browser main thread stays responsive (no "page
    // unresponsive" freeze) and the GPU does the work. CPU-tier demos
    // route only :ask/:models and keep plain lines local (3D).
    let route_all = mlpl_web_demos::capability_for(demo.name).requires_connect;
    crate::connect::dispatch_demo_line(line, entries, route_all, cont)
}

//! Rendering helpers for REPL/tutorial history entries.
//! Extracted from main.rs to keep that module under the
//! sw-checklist file-LOC budget.

use yew::prelude::*;

use mlpl_web_eval::state::{EntryKind, HistoryEntry};
use mlpl_web_eval::summary;

fn percent_encode(s: &str) -> String {
    let mut out = String::with_capacity(s.len());
    for b in s.bytes() {
        let safe = b.is_ascii_alphanumeric() || matches!(b, b'-' | b'_' | b'.' | b'~');
        if safe {
            out.push(b as char);
        } else {
            out.push_str(&format!("%{b:02X}"));
        }
    }
    out
}

/// Split an MLPL line at the first inline `#` comment that
/// is not inside a string literal. Returns `(code, comment)`
/// with comment as `Some(text)` when present (without the
/// leading `#`, trimmed). MLPL's parser already drops `#`
/// comments; this is purely for the UI to render the
/// commentary as an annotation alongside the code.
fn render_input_line(input: &str) -> Html {
    let (code, comment) = mlpl_web_tutorial::split_inline_comment(input);
    // Saga 29 step 025: route the comment text through the markdown-ish renderer so
    // `[[term]]` inside an MLPL `# comment` becomes a clickable glossary link. Code (the
    // part before `#`) stays a plain string -- the lexer parses MLPL source there and
    // [[ would be ambiguous with array literals.
    let comment_html = match comment {
        Some(c) => html! {
            <span class="line-comment">
                {" # "}
                { mlpl_web_path_body::render_inline(c) }
            </span>
        },
        None => html! {},
    };
    html! {
        <div class="input-line">
            <span class="prompt">{"mlpl> "}</span>
            { code }
            { comment_html }
        </div>
    }
}

fn render_svg_body(svg: &str) -> Html {
    let svg_html = Html::from_html_unchecked(AttrValue::from(svg.to_string()));
    let href = format!("data:image/svg+xml;charset=utf-8,{}", percent_encode(svg));
    html! {
        <div class="svg-output">
            { svg_html }
            <a class="svg-download" href={href} download="mlpl.svg" title="Download SVG" aria-label="Download SVG">{"\u{2b07}"}</a>
        </div>
    }
}

pub fn render_entry(entry: &HistoryEntry) -> Html {
    match entry.kind {
        EntryKind::Narration => render_narration(entry),
        EntryKind::Running => render_running(entry),
        _ => html! {
            <div class="entry">
                { render_input_line(&entry.input) }
                { render_result_body(entry) }
            </div>
        },
    }
}

/// Demo narration: prose framing with no `mlpl>` prompt. `input` is the
/// heading, `output` the body, routed through the path_body markdown-ish
/// renderer so bullets, **bold**, `code`, and `[[glossary-term]]` links work.
fn render_narration(entry: &HistoryEntry) -> Html {
    html! {
        <div class="narration">
            <div class="narration-heading">{ &entry.input }</div>
            <div class="narration-body">{ mlpl_web_path_body::render_body(&entry.output) }</div>
        </div>
    }
}

/// "Currently evaluating" placeholder. The CSS spinner keeps animating during
/// the JS-blocking WASM eval (CSS animations run on the compositor). The
/// telemetry panel is keyed by eval generation so a loaded demo (which reuses
/// one running-entry slot across lines) remounts it per line instead of
/// freezing a propless component on the first line's generation.
fn render_running(entry: &HistoryEntry) -> Html {
    html! {
        <div class="entry running">
            { render_input_line(&entry.input) }
            <div class="output-line running-line">
                <span class="spinner" aria-hidden="true"></span>
                <span class="running-text">{ &entry.output }</span>
            </div>
            <crate::telemetry_panel::TelemetryPanel
                key={mlpl_web_eval::telemetry_trace::current_gen()} />
        </div>
    }
}

/// The output region for a completed entry: an interactive Plotly panel, an
/// inline SVG, an error block, a collapsible stats summary, or plain text.
fn render_result_body(entry: &HistoryEntry) -> Html {
    let out = entry.output.trim_start();
    if !entry.is_error && out.starts_with(crate::plotly_panel::PLOTLY_MARKER) {
        return html! { <crate::plotly_panel::PlotlyPanel payload={ entry.output.clone() } /> };
    }
    if !entry.is_error && out.starts_with("<svg") {
        return render_svg_body(&entry.output);
    }
    if entry.is_error {
        return html! { <pre class={"output-line error"}>{ &entry.output }</pre> };
    }
    let Some(s) = summary::summarize(&entry.output) else {
        return html! { <pre class={"output-line"}>{ &entry.output }</pre> };
    };
    let line = format!(
        "{}  min={}  max={}  mean={}  median={}  std={}",
        s.shape,
        summary::fmt_stat(s.min),
        summary::fmt_stat(s.max),
        summary::fmt_stat(s.mean),
        summary::fmt_stat(s.median),
        summary::fmt_stat(s.std),
    );
    html! {
        <details class="output-summary">
            <summary>{ line }</summary>
            <pre class={"output-line"}>{ &entry.output }</pre>
        </details>
    }
}

