103	fn schedule_demo_line(
104	    session: Rc<RefCell<WasmSession>>,
105	    history: UseStateHandle<Vec<HistoryEntry>>,
106	    mut entries: Vec<HistoryEntry>,
107	    demo: &'static mlpl_web_demos::Demo,
108	    idx: usize,
109	) {
110	    let lines = demo.lines;
111	    if idx >= lines.len() {
112	        // Last line ran -- append the takeaway narration panel
113	        // and paint the final history state.
114	        entries.push(HistoryEntry {
115	            input: "What just happened".to_string(),
116	            output: demo.takeaway.to_string(),
117	            is_error: false,
118	            kind: EntryKind::Narration,
