1	//! Saga 21.5 step 008: browser-only `RemoteEvaluator` impls.
2	//!
3	//! Lifted out of `eval.rs` so the parent module stays under its
4	//! 500-line file budget. Every fn is `#[cfg(target_arch =
5	//! "wasm32")]` because the entire module body would otherwise
6	//! force `gloo::net` + `wasm_bindgen_futures` on native builds.
7	//! `cargo test` compiles this file but elides every function;
8	//! the WASM build (`scripts/build-pages.sh`) wires them in.
9	//!
10	//! Saga 77: HTTP helper bodies (`wasm_create_session`,
11	//! `wasm_eval_stream`, `wasm_eval_stream_inner`) moved to
12	//! `eval_wasm_helpers.rs` so the parent stays under the
13	//! module-function-count limit.
14	
15	#![cfg(target_arch = "wasm32")]
16	
17	use crate::eval::current_connect_url_from_window;
18	use crate::eval::{Evaluator, MetricCb, RemoteEvaluator, ResultCb, StreamCb};
19	use crate::eval_wasm_helpers::wasm_eval;
20	use crate::eval_wasm_stream::wasm_eval_stream;
21	
22	thread_local! {
23	    // One persistent RemoteEvaluator per page so the server-side
24	    // session (workspace state) is reused across submitted lines.
25	    static CONNECT_EVALUATOR: std::cell::RefCell<Option<RemoteEvaluator>> =
26	        const { std::cell::RefCell::new(None) };
27	}
28	
29	/// Connect-mode one-shot eval. When `?connect=<url>` is present in
30	/// the page URL, route `program` to that `mlpl-serve` over the
31	/// REST eval API (async, server-side) and fire `on_result` with
32	/// the server's value -- so `llm_call` / MLX-GPU work run on the
33	/// server and never block (or panic) the browser. Returns true
34	/// when it took the eval; false (leaving `on_result` uncalled)
35	/// when no connect URL is set, so the caller does local eval.
36	pub fn connect_eval(program: &str, on_result: ResultCb) -> bool {
37	    let Some(url) = current_connect_url_from_window() else {
38	        return false;
39	    };
40	    // The browser will block this fetch (https page -> http server) before it
41	    // leaves the tab. Short-circuit with a clear explanation instead of a
42	    // cryptic "Failed to fetch".
43	    if let Some(reason) = crate::connect_guard::connect_blocked_reason() {
44	        on_result(format!("error: {reason}"));
45	        return true;
46	    }
47	    CONNECT_EVALUATOR.with(|cell| {
48	        if cell.borrow().is_none() {
49	            *cell.borrow_mut() = Some(RemoteEvaluator::new(url));
50	        }
51	        cell.borrow()
52	            .as_ref()
53	            .expect("evaluator set above")
54	            .eval(program, on_result);
55	    });
56	    true
57	}
58	
59	/// Connect eval that STREAMS per-step metrics into `loss_trace` when
60	/// the program contains a train block -- feeding the live loss panel --
61	/// and takes the plain JSON path otherwise (which carries the 3D-viz
62	/// payload the stream's `done` frame does not). Same contract as
63	/// [`connect_eval`]: true when it took the eval. Metric frames land in
64	/// THIS eval's generation, so concurrent evals never intermix curves.
65	pub fn connect_eval_auto(program: &str, on_result: ResultCb) -> bool {
66	    if !crate::connect_guard::program_streams_metrics(program) {
67	        return connect_eval(program, on_result);
68	    }
69	    let Some(url) = current_connect_url_from_window() else {
70	        return false;
71	    };
72	    if let Some(reason) = crate::connect_guard::connect_blocked_reason() {
73	        on_result(format!("error: {reason}"));
74	        return true;
75	    }
76	    let gen_id = crate::telemetry_trace::current_gen();
77	    CONNECT_EVALUATOR.with(|cell| {
78	        if cell.borrow().is_none() {
79	            *cell.borrow_mut() = Some(RemoteEvaluator::new(url));
80	        }
81	        cell.borrow()
82	            .as_ref()
83	            .expect("evaluator set above")
84	            .eval_stream(
85	                program,
86	                Box::new(move |m| crate::loss_trace::push(gen_id, &m.name, m.value)),
87	                Box::new(move |outcome| on_result(outcome.into_display().0)),
88	            );
89	    });
90	    true
91	}
