93	impl Evaluator for RemoteEvaluator {
94	    fn eval(&self, program: &str, on_result: ResultCb) {
95	        let base = self.base_url().to_string();
96	        let state = self.state_handle();
97	        let program = program.to_string();
98	        wasm_bindgen_futures::spawn_local(async move {
99	            let result = wasm_eval(&base, &state, &program).await;
100	            on_result(result);
101	        });
102	    }
103	    fn clear(&self) {
104	        self.clear_state();
105	    }
106	}
107	
108	impl RemoteEvaluator {
109	    /// Browser streaming-eval. Spawns a local future that POSTs
110	    /// to `/eval_stream`, reads the response body as a UTF-8
111	    /// stream, parses SSE frames, fires `on_metric` per metric,
112	    /// and finally fires `on_result` with the terminal outcome.
113	    pub fn eval_stream(&self, program: &str, on_metric: MetricCb, on_result: StreamCb) {
114	        let base = self.base_url().to_string();
115	        let state = self.state_handle();
116	        let program = program.to_string();
117	        wasm_bindgen_futures::spawn_local(async move {
118	            let outcome = wasm_eval_stream(&base, &state, &program, on_metric).await;
119	            on_result(outcome);
120	        });
121	    }
122	
123	    /// Browser cancel: fire `/v1/sessions/<id>/cancel`. No-op
124	    /// when no session has been minted yet.
125	    pub fn cancel(&self) {
126	        let Some(session_id) = self.current_session_id() else {
127	            return;
128	        };
129	        let Some(token) = self.current_token() else {
130	            return;
131	        };
132	        let url = format!(
133	            "{}/v1/sessions/{}/cancel",
134	            self.base_url().trim_end_matches('/'),
135	            session_id
136	        );
137	        wasm_bindgen_futures::spawn_local(async move {
138	            if let Ok(req) = gloo::net::http::Request::post(&url)
139	                .header("Authorization", &format!("Bearer {token}"))
140	                .body(String::new())
141	            {
142	                let _ = req.send().await;
143	            }
144	        });
145	    }
146	
147	    /// Browser viz fetch: `GET /v1/viz/<id>` with bearer auth.
148	    /// Returns `(bytes, content_type)` so the caller can render
149	    /// an `<img>` (for `image/*`) or an `<iframe srcdoc>` (for
150	    /// `text/html`). Native equivalent lives in `eval.rs`.
151	    pub async fn fetch_viz_async(
152	        &self,
153	        viz_url: &str,
154	        bearer: &str,
155	    ) -> Result<(Vec<u8>, String), String> {
156	        let url = crate::eval::resolve_viz_url(self.base_url(), viz_url);
157	        let resp = gloo::net::http::Request::get(&url)
158	            .header("Authorization", &format!("Bearer {bearer}"))
159	            .send()
160	            .await
161	            .map_err(|e| e.to_string())?;
162	        if !resp.ok() {
163	            return Err(format!("fetch_viz: {}", resp.status()));
164	        }
165	        let content_type = resp
166	            .headers()
167	            .get("content-type")
168	            .unwrap_or_else(|| "application/octet-stream".to_string());
169	        let bytes = resp.binary().await.map_err(|e| e.to_string())?;
170	        Ok((bytes, content_type))
171	    }
172	}

