27	/// Build the full `:ask` program: the question as the user prompt,
28	/// with the grounding/context riding in `llm_call`'s `system` field.
29	#[must_use]
30	pub fn ask_program(question: &str, history: &[HistoryEntry]) -> String {
31	    let esc = |s: &str| s.replace('\\', "\\\\").replace('"', "\\\"");
32	    let question = esc(question.trim().trim_matches('"').trim());
33	    let system = esc(&build_ask_system(history));
34	    let (url, model) = crate::context::ask_endpoint();
35	    format!("llm_call(\"{url}\", \"{question}\", \"{model}\", \"{system}\")")
36	}
