36	pub(crate) async fn wasm_eval_stream(
37	    base_url: &str,
38	    state: &RefCell<Option<RemoteSession>>,
39	    program: &str,
40	    mut on_metric: MetricCb,
41	) -> StreamOutcome {
42	    match wasm_eval_stream_inner(base_url, state, program, &mut on_metric).await {
43	        Ok(outcome) => outcome,
44	        Err(message) => StreamOutcome::Error { message },
45	    }
46	}
