91	/// Drive the response `ReadableStream` chunk by chunk through an
92	/// `SseFeed`. Falls back to a whole-body read (frames batch at body
93	/// end) when the browser exposes no stream.
94	async fn read_sse_stream(
95	    resp: &gloo::net::http::Response,
96	    on_metric: &mut MetricCb,
97	) -> Result<StreamOutcome, String> {
98	    let Some(stream) = resp.body() else {
