114	    pub session_id: Uuid,
115	    pub created_at: u64,
116	    pub last_eval_at: Option<u64>,
117	    pub vars: Vec<VarSnapshot>,
118	    pub models: Vec<String>,
119	    pub tokenizers: Vec<String>,
120	    pub experiments: Vec<String>,
121	    pub more: usize,
122	}
123	
124	/// `POST /v1/sessions` -- no auth. Creates a fresh
125	/// session and returns its id + bearer token. Also
126	/// registers the session in the parallel interrupt
127	/// map (Saga 21.5 step 003) so `/cancel` is reachable
128	/// for it from the very first call.
129	pub async fn create_session_handler(State(state): State<AppState>) -> impl IntoResponse {
130	    let (id, token) = crate::sessions::create_session(&state.sessions, &state.interrupts).await;
131	    (
132	        StatusCode::OK,
133	        Json(CreateSessionResponse {
134	            session_id: id,
135	            token,
136	        }),
137	    )
138	}
139	
140	/// `POST /v1/sessions/{id}/eval` -- requires bearer when
141	/// `auth_mode == Required`. Lex + parse, then run the program OFF the
142	/// global session lock: the session is taken out of the map, evaluated
143	/// on a `spawn_blocking` task, and reinserted -- so a long eval never
144	/// blocks new-session creation or other serving (notably the telemetry
145	/// panel's `/v1/stats`). An `AbortGuard` trips the session interrupt if
146	/// the client disconnects mid-eval (a shift-reload), so the eval aborts
147	/// at its next checkpoint instead of orphaning and wedging the server.
148	pub async fn eval_handler(
149	    State(state): State<AppState>,
150	    Path(id): Path<Uuid>,
151	    headers: HeaderMap,
152	    Json(body): Json<EvalRequest>,
153	) -> Result<Json<EvalResponse>, (StatusCode, Json<ErrorResponse>)> {
154	    let tokens =
155	        lex(&body.program).map_err(|e| (StatusCode::BAD_REQUEST, json_err(format!("{e:?}"))))?;
156	    let stmts =
157	        parse(&tokens).map_err(|e| (StatusCode::BAD_REQUEST, json_err(format!("{e:?}"))))?;
158	    let (session, interrupt) = take_session_for_eval(&state, id, &headers).await?;
159	    let rx = spawn_eval(&state, id, session, stmts);
160	    let mut guard = AbortGuard {
161	        interrupt,
162	        armed: true,
163	    };
164	    let result = rx.await;
165	    guard.armed = false;
166	    match result {
167	        Ok(Ok(resp)) => Ok(Json(resp)),
168	        Ok(Err(e)) => Err((StatusCode::BAD_REQUEST, json_err(e))),
169	        Err(_) => Err((
170	            StatusCode::INTERNAL_SERVER_ERROR,
171	            json_err("eval task dropped"),
172	        )),
173	    }
174	}
175	
176	/// Trips a session's interrupt when dropped while still armed -- the
177	/// cancel-on-disconnect mechanism. `eval_handler` disarms it on normal
178	/// completion; if the handler future is instead dropped (client
179	/// disconnect), the drop sets the interrupt and the in-flight eval
180	/// aborts at its next checkpoint.
181	struct AbortGuard {
182	    interrupt: Interrupt,
183	    armed: bool,
184	}
185	
186	impl Drop for AbortGuard {
187	    fn drop(&mut self) {
188	        if self.armed {
189	            self.interrupt.set();
190	        }
191	    }
192	}
193	
194	/// Authenticate, take the session OUT of the map (so the eval does not
195	/// hold the global write lock), reset + install its interrupt, and wire
196	/// the peer dispatcher. Returns the owned session + a clone of its
197	/// interrupt for the `AbortGuard`.
198	async fn take_session_for_eval(
199	    state: &AppState,
200	    id: Uuid,
201	    headers: &HeaderMap,
202	) -> Result<(crate::sessions::Session, Interrupt), (StatusCode, Json<ErrorResponse>)> {
203	    let unauthorized = || {
204	        (
205	            StatusCode::UNAUTHORIZED,
206	            json_err("missing or invalid authorization"),
207	        )
208	    };
209	    let entry = state
210	        .interrupts
211	        .read()
212	        .await
213	        .get(&id)
214	        .cloned()
215	        .ok_or((StatusCode::NOT_FOUND, json_err("unknown session")))?;
216	    if state.auth_mode == AuthMode::Required {
217	        let provided = extract_bearer(headers).ok_or_else(unauthorized)?;
218	        if !check_token(provided, &entry.token) {
219	            return Err(unauthorized());
220	        }
221	    }
222	    entry.interrupt.reset();
223	    let mut session = state
224	        .sessions
225	        .write()
226	        .await
227	        .remove(&id)
228	        .ok_or((StatusCode::NOT_FOUND, json_err("unknown session")))?;
229	    session.env.set_interrupt(entry.interrupt.clone());
230	    session
231	        .env
232	        .set_peer_dispatcher(Arc::new(crate::server::RemoteMlxDispatcher::new(
233	            state.peers.clone(),
234	            state.peer_sessions.clone(),
235	        )));
236	    Ok((session, entry.interrupt))
237	}
238	
239	/// Spawn the eval as a detached task (so it unwinds cleanly even if the
240	/// handler future is dropped on disconnect) and deliver the built
241	/// response over a oneshot.
242	fn spawn_eval(
243	    state: &AppState,
244	    id: Uuid,
245	    session: crate::sessions::Session,
246	    stmts: Vec<mlpl_parser::Expr>,
247	) -> oneshot::Receiver<Result<EvalResponse, String>> {
248	    let (tx, rx) = oneshot::channel();
249	    let state = state.clone();
250	    tokio::spawn(async move {
251	        let resp = run_eval(&state, id, session, stmts).await;
252	        let _ = tx.send(resp);
253	    });
254	    rx
255	}
256	
257	/// Body of the eval task: evaluate on a blocking thread, clear the
258	/// env's per-eval hooks, build the response (with viz attach) on
259	/// success, ALWAYS reinsert the session, and flush persistence.
260	async fn run_eval(
261	    state: &AppState,
262	    id: Uuid,
263	    mut session: crate::sessions::Session,
264	    stmts: Vec<mlpl_parser::Expr>,
265	) -> Result<EvalResponse, String> {
266	    let join = tokio::task::spawn_blocking(move || {
267	        let value = eval_program_value(&stmts, &mut session.env);
268	        (session, value)
269	    })
270	    .await;
271	    let (mut session, value) = join.map_err(|_| "eval task panicked".to_string())?;
272	    session.env.clear_peer_dispatcher();
273	    session.env.clear_interrupt();
274	    // Surface any user-visible notices (e.g. a silent GPU->CPU fallback)
275	    // by prepending them to the result -- but not to an SVG/viz payload,
276	    // whose leading `<svg` the client sniffs for.
277	    let notices = session.env.take_notices();
278	    let out = match value {
279	        Ok(v) => {
280	            session.last_eval_at = Some(crate::sessions::now_unix_seconds());
281	            let kind = value_kind(&v);
282	            let mut formatted = format!("{v}");
283	            if !notices.is_empty() && !formatted.trim_start().starts_with("<svg") {
284	                formatted = format!("{}\n{formatted}", notices.join("\n"));
285	            }
286	            let attached = crate::viz_storage::attach_viz(&state.viz, &formatted, kind).await;
287	            Ok(crate::eval_viz::build_eval_response(
288	                &v, kind, formatted, attached,
289	            ))
290	        }
291	        Err(e) => Err(format!("{e}")),
292	    };
293	    state.sessions.write().await.insert(id, session);
294	    crate::persist::maybe_flush(state).await;
295	    out
296	}
297	
298	/// `POST /v1/sessions/{id}/cancel` -- requires bearer
299	/// when `auth_mode == Required`. Flips the session's
300	/// shared `Interrupt` bool so any in-flight eval
301	/// observes the trip at its next loop / pre-builtin
302	/// checkpoint and raises `EvalError::Cancelled`. Idempotent:
303	/// a second call after the bool is already set is a no-op
304	/// at the eval level. Uses the parallel `InterruptMap`
305	/// (Saga 21.5 step 003) so it can run while another
306	/// request holds the sessions write lock. Saga 21.5
307	/// step 003.
308	pub async fn cancel_handler(
309	    State(state): State<AppState>,
310	    Path(id): Path<Uuid>,
311	    headers: HeaderMap,
312	) -> Result<Json<CancelResponse>, (StatusCode, Json<ErrorResponse>)> {
313	    let not_found = || (StatusCode::NOT_FOUND, json_err("unknown session"));
314	    let unauthorized = || {
315	        (
316	            StatusCode::UNAUTHORIZED,
317	            json_err("missing or invalid authorization"),
318	        )
319	    };
320	    let entry = state
321	        .interrupts
322	        .read()
323	        .await
324	        .get(&id)
325	        .cloned()
326	        .ok_or_else(not_found)?;
327	    if state.auth_mode == AuthMode::Required {
328	        let provided = extract_bearer(&headers).ok_or_else(unauthorized)?;
329	        if !check_token(provided, &entry.token) {
330	            return Err(unauthorized());
331	        }
332	    }
333	    entry.interrupt.set();
334	    Ok(Json(CancelResponse { cancelled: true }))
335	}
336	
337	/// `POST /v1/reset` -- no auth, no session id. Sets the interrupt flag
338	/// on EVERY registered session so any in-flight eval (notably a
339	/// training loop) aborts at its next checkpoint and releases the
340	/// sessions write-lock. This is the UI's recovery path when it has lost
341	/// its session id+token (e.g. after a shift-reload during a heavy
342	/// demo): a fresh page can free the backend without a process restart.
343	/// It deliberately needs no bearer (the reloaded page has none) and
344	/// uses the lock-free interrupt map, so it runs even while an orphaned
345	/// eval holds the sessions write-lock. Threat model: loopback/LAN; the
346	/// blast radius is "cancel in-flight work", not data access or code
347	/// execution. Returns how many sessions were signalled.
348	pub async fn reset_handler(State(state): State<AppState>) -> impl IntoResponse {
349	    let interrupts = state.interrupts.read().await;
350	    for entry in interrupts.values() {
351	        entry.interrupt.set();
352	    }
353	    Json(ResetResponse {
354	        cancelled: interrupts.len(),
355	    })
356	}
357	
358	/// `GET /v1/health` -- no auth. Liveness +
359	/// `CARGO_PKG_VERSION`.
360	pub async fn health_handler() -> impl IntoResponse {
361	    Json(HealthResponse {
362	        status: "ok",
363	        version: env!("CARGO_PKG_VERSION"),
364	    })
365	}
366	
367	/// `GET /v1/sessions/{id}/inspect` -- requires
368	/// bearer when `auth_mode == Required`. Returns a
369	/// JSON snapshot of the session's workspace
370	/// (variable names + shapes + `[param]` tags, model
371	/// names, tokenizer names, experiment names). Vars
372	/// capped at 200 entries; the `more` field reports
373	/// how many were truncated.
374	pub async fn inspect_handler(
375	    State(state): State<AppState>,
376	    Path(id): Path<Uuid>,
377	    headers: HeaderMap,
378	) -> Result<Json<InspectResponse>, (StatusCode, Json<ErrorResponse>)> {
379	    let sessions = state.sessions.read().await;
380	    let session = sessions
381	        .get(&id)
382	        .ok_or((StatusCode::NOT_FOUND, json_err("unknown session")))?;
383	    if state.auth_mode == AuthMode::Required {
384	        let provided = extract_bearer(&headers).ok_or((
385	            StatusCode::UNAUTHORIZED,
386	            json_err("missing or invalid authorization"),
387	        ))?;
388	        if !check_token(provided, &session.token) {
389	            return Err((
390	                StatusCode::UNAUTHORIZED,
391	                json_err("missing or invalid authorization"),
392	            ));
393	        }
394	    }
395	    Ok(Json(snapshot_env(&session.env)))
396	}
397	
398	/// `GET /v1/sessions/{id}` -- requires bearer when
399	/// `auth_mode == Required`. Returns the session's bearer-token
400	/// signed metadata: creation + last-eval timestamps plus the
401	/// same workspace summary `/inspect` returns. Saga 21.5 step
402	/// 009 -- backs `mlpl-repl --connect --session <id>`.
403	pub async fn session_meta_handler(
404	    State(state): State<AppState>,
405	    Path(id): Path<Uuid>,
406	    headers: HeaderMap,
407	) -> Result<Json<SessionMetaResponse>, (StatusCode, Json<ErrorResponse>)> {
408	    let sessions = state.sessions.read().await;
409	    let session = sessions
410	        .get(&id)
411	        .ok_or((StatusCode::NOT_FOUND, json_err("unknown session")))?;
412	    if state.auth_mode == AuthMode::Required {
413	        let provided = extract_bearer(&headers).ok_or((
414	            StatusCode::UNAUTHORIZED,
415	            json_err("missing or invalid authorization"),
416	        ))?;
417	        if !check_token(provided, &session.token) {
418	            return Err((
419	                StatusCode::UNAUTHORIZED,
420	                json_err("missing or invalid authorization"),
421	            ));
422	        }
423	    }
424	    let snap = snapshot_env(&session.env);
425	    Ok(Json(SessionMetaResponse {
426	        session_id: id,
427	        created_at: session.created_at,
428	        last_eval_at: session.last_eval_at,
429	        vars: snap.vars,
430	        models: snap.models,
431	        tokenizers: snap.tokenizers,
432	        experiments: snap.experiments,
433	        more: snap.more,
434	    }))
435	}
436	
437	fn snapshot_env(env: &Environment) -> InspectResponse {
438	    let mut vars: Vec<VarSnapshot> = env
439	        .vars_iter()
440	        .map(|(name, arr)| VarSnapshot {
441	            name: name.clone(),
442	            shape: arr.shape().dims().to_vec(),
443	            is_param: env.is_param(name),
444	        })
445	        .collect();
446	    vars.sort_by(|a, b| a.name.cmp(&b.name));
447	    let total = vars.len();
448	    let more = total.saturating_sub(VARS_CAP);
449	    vars.truncate(VARS_CAP);
450	    let mut models: Vec<String> = env.models_iter().map(|(n, _)| n.clone()).collect();
451	    models.sort();
452	    let mut tokenizers: Vec<String> = env.tokenizers_iter().map(|(n, _)| n.clone()).collect();
453	    tokenizers.sort();
454	    let mut experiments: Vec<String> = env
455	        .experiment_log()
456	        .iter()
457	        .map(|r| r.name.clone())
458	        .collect();
459	    experiments.sort();
460	    experiments.dedup();
461	    InspectResponse {
462	        vars,
463	        models,
464	        tokenizers,
465	        experiments,
466	        more,
467	    }
468	}
469	
470	pub(crate) fn json_err(msg: impl Into<String>) -> Json<ErrorResponse> {
471	    Json(ErrorResponse { error: msg.into() })
472	}
473	
474	/// Saga 21.5 step 003: clone the session's shared `Interrupt`
475	/// out of the parallel map, `reset()` it (so a prior cancel
476	/// doesn't contaminate this call), and install it into the
477	/// session's env. Shared by `eval_handler` (this module) and the
478	/// SSE `eval_stream_handler` so cancellation behavior is
479	/// identical across the two transports.
480	pub(crate) async fn install_session_interrupt(
481	    state: &AppState,
482	    id: &Uuid,
483	    session: &mut crate::sessions::Session,
484	) {
485	    if let Some(entry) = state.interrupts.read().await.get(id).cloned() {
486	        entry.interrupt.reset();
487	        session.env.set_interrupt(entry.interrupt);
488	    }
489	}
490	
491	pub(crate) fn value_kind(value: &Value) -> &'static str {
492	    match value {
493	        Value::Array(_) => "array",
494	        Value::Str(_) => "string",
495	        Value::Model(_) => "model",
496	        Value::Tokenizer(_) => "tokenizer",
497	        Value::DeviceTensor { .. } => "device-tensor",
498	        Value::BuiltinRef { .. } => "builtin-ref",
499	        Value::Record { .. } => "record",
500	        Value::StrList { .. } => "string-list",
501	        Value::Result { .. } => "result",
502	    }
503	}
