1	//! Per-eval live loss series streamed from `event: metric` SSE frames.
2	//!
3	//! Generation-keyed twin of `telemetry_trace`, but pure std (no wasm
4	//! gate) so the reducer logic tests natively: the WASM connect path
5	//! pushes one sample per metric frame, the `LiveLossPanel` polls
6	//! `seq`/`series` to repaint, and the result callback `summary`s the
7	//! generation into a persistent one-liner when the eval finishes.
8	
9	use std::cell::RefCell;
10	use std::collections::HashMap;
11	
12	const KEEP: u32 = 6;
13	const CAP: usize = 4096;
14	
15	/// Streamed series keyed by metric name in first-seen order, plus a
16	/// monotonic push counter the panel polls for repaint.
17	#[derive(Default)]
18	struct Trace {
19	    series: Vec<(String, Vec<f64>)>,
20	    seq: u32,
21	}
22	
23	thread_local! {
24	    static TRACES: RefCell<HashMap<u32, Trace>> = RefCell::new(HashMap::new());
25	}
26	
27	/// Append one streamed metric sample to generation `gen_id`. Series are
28	/// capped at `CAP` points (train demos stay far below); generations
29	/// more than `KEEP` behind this one are pruned, mirroring
30	/// `telemetry_trace`.
31	pub fn push(gen_id: u32, name: &str, value: f64) {
32	    TRACES.with(|t| {
33	        let mut m = t.borrow_mut();
34	        m.retain(|&k, _| gen_id.saturating_sub(KEEP) < k);
35	        let trace = m.entry(gen_id).or_default();
36	        let idx = match trace.series.iter().position(|(n, _)| n == name) {
37	            Some(i) => i,
38	            None => {
39	                trace.series.push((name.to_string(), Vec::new()));
40	                trace.series.len() - 1
41	            }
42	        };
43	        let buf = &mut trace.series[idx].1;
44	        if buf.len() < CAP {
45	            buf.push(value);
46	        }
47	        trace.seq = trace.seq.wrapping_add(1);
48	    });
49	}
50	
51	/// Monotonic per-generation push counter (0 for unknown generations).
52	#[must_use]
53	pub fn seq(gen_id: u32) -> u32 {
54	    TRACES.with(|t| t.borrow().get(&gen_id).map_or(0, |tr| tr.seq))
55	}
56	
57	/// The `(train, val)` series for `gen_id`, empty when unknown. Val is
58	/// the first series whose name starts with `val`; train is the first
59	/// non-val series, preferring a name containing `loss` (so a stray
60	/// `acc_metric` still charts when it is all the program emits).
61	#[must_use]
62	pub fn series(gen_id: u32) -> (Vec<f64>, Vec<f64>) {
63	    TRACES.with(|t| {
64	        t.borrow().get(&gen_id).map_or_else(
65	            || (Vec::new(), Vec::new()),
66	            |tr| {
67	                let (train, val) = picks(&tr.series);
68	                (
69	                    train.cloned().unwrap_or_default(),
70	                    val.cloned().unwrap_or_default(),
71	                )
72	            },
73	        )
74	    })
75	}
76	
77	/// `(train, val)` series selection shared by `series` and `summary`.
78	fn picks(series: &[(String, Vec<f64>)]) -> (Option<&Vec<f64>>, Option<&Vec<f64>>) {
79	    let non_val = |n: &str| !n.starts_with("val");
80	    let train = series
81	        .iter()
82	        .find(|(n, _)| non_val(n) && n.contains("loss"))
83	        .or_else(|| series.iter().find(|(n, _)| non_val(n)))
84	        .map(|(_, b)| b);
85	    let val = series
86	        .iter()
87	        .find(|(n, _)| n.starts_with("val"))
88	        .map(|(_, b)| b);
89	    (train, val)
90	}
91	
92	/// One-line text record of the streamed loss (sparkline + step count +
93	/// final values), CONSUMING the generation -- appended under the result
94	/// so the live curve leaves a durable trace once the panel unmounts.
95	/// `None` when nothing was streamed.
96	#[must_use]
97	pub fn summary(gen_id: u32) -> Option<String> {
98	    let trace = TRACES.with(|t| t.borrow_mut().remove(&gen_id))?;
99	    let (train, val) = picks(&trace.series);
100	    let train = train?;
101	    let last = *train.last()?;
102	    let spark = mlpl_monitor_types::spark::sparkline(&percents(train), 100);
103	    let val_note = val
104	        .and_then(|v| v.last())
105	        .map(|v| format!("  val {v:.4}"))
106	        .unwrap_or_default();
107	    Some(format!(
108	        "live loss {spark}  {} steps, final {last:.4}{val_note}",
109	        train.len()
110	    ))
111	}
112	
113	/// Normalize a series into 0..=100 integer percentages for the text
114	/// sparkline (min -> 0, max -> 100; a constant series reads as flat
115	/// 50s). The clamp bounds the value, so the cast cannot truncate.
116	#[allow(clippy::cast_possible_truncation, clippy::cast_sign_loss)]
117	fn percents(vals: &[f64]) -> Vec<u32> {
118	    let (min, max) = vals
119	        .iter()
120	        .fold((f64::INFINITY, f64::NEG_INFINITY), |(lo, hi), &v| {
121	            (lo.min(v), hi.max(v))
122	        });
123	    let range = max - min;
124	    vals.iter()
125	        .map(|&v| {
126	            if range > 0.0 {
127	                ((v - min) / range * 100.0).clamp(0.0, 100.0).round() as u32
128	            } else {
129	                50
130	            }
131	        })
132	        .collect()
133	}
134	
135	/// Text sparkline of a loss series (min -> lowest bar, max -> highest),
136	/// for the LOSS row the telemetry panel time-aligns with its hardware
137	/// rows. Empty input yields an empty string.
138	#[must_use]
139	pub fn spark_line(vals: &[f64]) -> String {
140	    mlpl_monitor_types::spark::sparkline(&percents(vals), 100)
141	}

